5f0b", "type": "concept", "title": "Naturalization"}, {"id": "c82954fa-7cd5-4092-ba4e-320700d369f8", "type": "concept", "title": "Metalinguistic commentary"}], "description": "Students learn how assumptions about correctness, clarity, beauty, intelligence, and authenticity shape social life."}, {"id": "de6108e4-1dc0-478e-bad9-87d838ffe25b", "type": "subtopic", "title": "Linguistic markets and symbolic power", "children": [{"id": "d3564642-c128-4838-9515-e41aefb5cda9", "type": "concept", "title": "Bourdieu"}, {"id": "e3588d09-4faf-4ff1-96bd-9ca5016a3296", "type": "concept", "title": "Linguistic capital"}, {"id": "42d6f64b-1809-42af-b292-87b31d346773", "type": "concept", "title": "Symbolic power"}, {"id": "961ed0fe-c209-4463-8dec-816ce1540fb2", "type": "concept", "title": "Legitimate language"}, {"id": "cbfce8cc-a653-404e-b5bf-fe1b64f6ff0b", "type": "concept", "title": "Market"}, {"id": "5af00b1d-2b7b-4d9c-862e-830e60b047f1", "type": "concept", "title": "Authority"}], "description": "This subtopic examines why some ways of speaking carry institutional value and others are penalized."}, {"id": "fa2b5703-e79d-4ed5-a94c-d05b7585ca60", "type": "subtopic", "title": "Institutional language power", "children": [{"id": "cc753dd4-189e-4a67-9d44-ada833eb6f7b", "type": "concept", "title": "Gatekeeping"}, {"id": "88f6ab94-9290-43ca-a33b-acfed60336ea", "type": "concept", "title": "Language testing"}, {"id": "8bba00b4-cc9f-4e8c-8090-0a18fac804d4", "type": "concept", "title": "Legal interpreting"}, {"id": "184709c0-e9ee-401b-b25e-d9895c4ad96e", "type": "concept", "title": "Plain language"}, {"id": "16dbfff9-04c2-4fa2-ad31-28bb90a61c98", "type": "concept", "title": "Institutional talk"}, {"id": "80ad8841-cb30-4e52-80ae-8d233eaa469b", "type": "concept", "title": "Bureaucratic language"}], "description": "Students analyze how schools, courts, workplaces, medicine, and governments regulate language."}]}, {"id": "6bec2d26-60a8-432a-88b1-f0c88ee93fb7", "type": "topic", "title": "Multilingualism, Code-Switching, and Translanguaging", "description": "Studies multilingual practice as normal, creative, strategic, and politically charged.", "children": [{"id": "a253ec7a-920c-44dd-a5da-477d3c39bdad", "type": "subtopic", "title": "Multilingual repertoires", "children": [{"id": "412bb769-f17f-4599-af0b-1c2531c4a176", "type": "concept", "title": "Repertoire"}, {"id": "fd8a2f95-6ae3-4ba9-ba9a-2b6a9262fdaf", "type": "concept", "title": "Polyglossia"}, {"id": "6f5163af-f7bb-48ff-b220-de85442afea0", "type": "concept", "title": "Diglossia"}, {"id": "3208b03a-d069-4f58-9b52-8db8952a27fb", "type": "concept", "title": "Language dominance"}, {"id": "ceb9c68b-8d09-4781-8d34-16f2b2d18dfc", "type": "concept", "title": "Heritage language"}, {"id": "9a55a150-1478-4e7b-b536-d378d5b42513", "type": "concept", "title": "Languaging"}], "description": "Students learn to describe language resources without assuming bounded, pure languages."}, {"id": "24729722-211c-4e7b-9b1f-e4c28a13fd1d", "type": "subtopic", "title": "Code-switching and code-mixing", "children": [{"id": "bd15b3db-dcbb-4465-9db7-8eef4bfa33ef", "type": "concept", "title": "Code-switching"}, {"id": "449744d3-3bb2-4a3c-b94d-80054360bd33", "type": "concept", "title": "Matrix language"}, {"id": "30586722-1bbf-473e-baf5-ffe55c34f9f9", "type": "concept", "title": "Insertion"}, {"id": "82204e89-9d80-4683-85e5-63d6ee58f638", "type": "concept", "title": "Alternation"}, {"id": "5cfebab7-69ba-4f2d-89e9-f9111d1a2adf", "type": "concept", "title": "Tag switching"}, {"id": "8be88d4f-2412-4179-9e27-d48b7bbe9338", "type": "concept", "title": "Conversational function"}], "description": "This subtopic explains how switching can signal topic, stance, audience, identity, humor, intimacy, or authority."}, {"id": "1b55e062-af40-4449-9dfa-bad4c40083b8", "type": "subtopic", "title": "Translanguaging and critique", "children": [{"id": "b5ae9b2d-ae32-40db-b06b-ef67ce64d9eb", "type": "concept", "title": "Translanguaging"}, {"id": "e01e9a8a-9