  goal = 'Linguistic Anthropology',
  summary = 'This course studies language as social action: how people use speech, writing, signing, silence, gesture, media, and digital communication to make meaning, claim identity, exercise power, create institutions, and sustain cultural life. This course explores linguistic anthropology, covering semiotics, pragmatics, language ideology, multilingualism, language socialization, discourse, language rights, endangerment, digital communication, and ethnographic methods.',
  data = $lianjson${"slug": "linguistic-anthropology", "title": "Linguistic Anthropology", "description": "This course studies language as social action: how people use speech, writing, signing, silence, gesture, media, and digital communication to make meaning, claim identity, exercise power, create institutions, and sustain cultural life. This course explores linguistic anthropology, covering semiotics, pragmatics, language ideology, multilingualism, language socialization, discourse, language rights, endangerment, digital communication, and ethnographic methods.", "topics": [{"id": "79439ae6-65bd-4d59-8af1-72314a0d7f74", "type": "topic", "title": "Linguistic Anthropology as a Field", "description": "Introduces linguistic anthropology as the study of language in social life, linking communicative practice to culture, power, identity, history, and interaction.", "children": [{"id": "77a90ddb-d32b-44d9-bd67-185cef511dab", "type": "subtopic", "title": "Language, culture, and communication", "children": [{"id": "473cff42-2ae1-4a4a-8b7f-d1fe642a3d11", "type": "concept", "title": "Communicative practice"}, {"id": "a0ad3305-4194-426a-909d-d3e263fd134b", "type": "concept", "title": "Culture"}, {"id": "f293305b-39bb-405e-b310-f63d77d3c3ba", "type": "concept", "title": "Context"}, {"id": "1da1609b-1db3-4f29-ac08-2005daae3d64", "type": "concept", "title": "Interaction"}, {"id": "8112c993-6245-40fc-966e-bc71b1f94442", "type": "concept", "title": "Meaning"}, {"id": "1cb1e36b-16b8-43d2-8469-0e37eb3845a9", "type": "concept", "title": "Social action"}], "description": "Students learn why language is not just a code for ideas but a social practice that creates relationships, categories, and institutions."}, {"id": "894d61f8-ac9b-408c-8255-031e353d2a5f", "type": "subtopic", "title": "Linguistic anthropology and adjacent fields", "children": [{"id": "cd3761fb-3f02-4327-8e28-614ca5e9f66d", "type": "concept", "title": "Linguistics"}, {"id": "1a8fc357-b5da-4aef-931d-20cc0d5d5d34", "type": "concept", "title": "Sociolinguistics"}, {"id": "6a2a9ac1-775c-4daa-abc1-d2e14a9b37cd", "type": "concept", "title": "Discourse analysis"}, {"id": "88aca69f-09b4-4a59-af01-2b55bdb35101", "type": "concept", "title": "Semiotics"}, {"id": "412fe996-bd21-434d-8408-14f3099071d6", "type": "concept", "title": "Ethnography"}, {"id": "44881acf-d5cc-48d4-a249-4ead19484f7a", "type": "concept", "title": "Pragmatics"}], "description": "This subtopic clarifies how linguistic anthropology overlaps with linguistics, sociolinguistics, discourse analysis, semiotics, and anthropology."}, {"id": "7f939051-6b30-465c-a408-4ee1f8409ffa", "type": "subtopic", "title": "Ethnographic attention to language", "children": [{"id": "70e160d2-95aa-4434-8f95-0a42f52a919d", "type": "concept", "title": "Fieldnotes"}, {"id": "b9627ad1-f146-4931-ac84-ef8209985f77", "type": "concept", "title": "Audio recording"}, {"id": "b96bcb74-1be7-43b5-a02a-3f870f717c1c", "type": "concept", "title": "Transcription"}, {"id": "8a813257-7e3d-4f8d-9c6f-688775605038", "type": "concept", "title": "Participant observation"}, {"id": "a5521a2b-b34d-4cb2-addb-090e07e7596c", "type": "concept", "title": "Speech event"}, {"id": "c5d7dc6b-acf7-42d8-89d7-072484add74f", "type": "concept", "title": "Interactional data"}], "description": "Students see how fieldwork turns ordinary talk, silence, gesture, texts, and media into analyzable evidence."}]}, {"id": "4e5c7448-3f02-48d0-b4d3-b16e7b6f45ca", "type": "topic", "title": "Language as Social Action", "description": "Builds the core idea that speaking, writing, signing, and silence do things in the world.", "children": [{"id": "8756488e-129f-4d19-b352-209940076367", "type": "subtopic", "title": "Speech acts and performativity", "children": [{"id": "c7ca95d3-a833-4c57-9066-0b1b322945aa", "type": "concept", "title": "Austin"}, {"id": "f2561f9b-6f36-40b2-b083-14d189391336", "type": "concept", "title": "Searle"}, {"id": "84eec543-60f8-40b4-82c4-cbfa3e5b3588", "type": "concept", "title": "Illocution"}, {"id": "d6caadd9-b102-4e83-926f-aea00ef405bb", "type": "concept", "title": "Perlocution"}, {"id": "e735df65-c0c3-40a6-b186-a97ba80df0f1", "type": "concept", "title": "Felicity conditions"}, {"id": "17693196-214b-4289-95ea-78d3f5996153", "type": "concept", "title": "Performatives"}], "description": "Students learn how utterances can promise, command, name, marry, apologize, insult, bless, threaten, or authorize."}, {"id": "6bc8a943-85fb-41e9-987f-cfa25a31fe7b", "type": "subtopic", "title": "Interactional order", "children": [{"id": "38cfead3-96d1-4ea9-b2ac-4a8b91465308", "type": "concept", "title": "Turn-taking"}, {"id": "1b8f7b0d-7b32-40cd-a0d5-ab63d7611129", "type": "concept", "title": "Repair"}, {"id": "d46a5d52-c640-4149-adf9-b48d4125b32c", "type": "concept", "title": "Adjacency pair"}, {"id": "57d3695c-54ff-4be7-ba05-352addf4d1dc", "type": "concept", "title": "Participation framework"}, {"id": "e197b3d1-2f83-4f62-86b6-8072cb9c6679", "type": "concept", "title": "Alignment"}, {"id": "4c0f8831-5bb1-43db-97c9-a5e0b7ef9c6e", "type": "concept", "title": "Footing"}], "description": "This subtopic examines turn-taking, repair, stance, alignment, and participation as social organization in real time."}, {"id": "1cdb2511-52de-4c03-bdb8-6681d51e6a68", "type": "subtopic", "title": "Language, silence, and embodiment", "children": [{"id": "4cd3505a-a4dc-4d1f-b47f-58bf8b1136ff", "type": "concept", "title": "Gesture"}, {"id": "54fdadfd-d9bb-4419-b425-bde6cfeb9310", "type": "concept", "title": "Gaze"}, {"id": "78efbd03-b7f1-4f75-a5a0-b07379281f42", "type": "concept", "title": "Embodiment"}, {"id": "fdcb2e53-cef3-4760-a34b-756f71e85bce", "type": "concept", "title": "Silence"}, {"id": "8f432baf-e63f-4342-8dbf-cb68d8e55b21", "type": "concept", "title": "Prosody"}, {"id": "28d42a16-c959-4f45-ab30-1528e68aee09", "type": "concept", "title": "Material context"}], "description": "Students analyze communication beyond words, including gesture, gaze, posture, silence, and material setting."}]}, {"id": "127d4a81-8eb1-441a-97ff-a7cc2872dad4", "type": "topic", "title": "Phonetics, Phonology, and Social Meaning", "description": "Connects sound patterns to social identity, perception, accent, stigma, indexicality, and linguistic difference.", "children": [{"id": "5d205ac6-5d79-4d9d-bf46-60df0209d01b", "type": "subtopic", "title": "Speech sounds and phonetic detail", "children": [{"id": "a19fb3e0-4d9d-4fa8-882a-69c1827b725d", "type": "concept", "title": "Place of articulation"}, {"id": "c8cbdb42-5b70-415e-9b1a-d07b4494e1c2", "type": "concept", "title": "Manner of articulation"}, {"id": "96eda66c-fb49-4c12-95db-331d2fb7e9d4", "type": "concept", "title": "Vowels"}, {"id": "85fcc9b1-4b04-419a-ac39-772c0642bd60", "type": "concept", "title": "Consonants"}, {"id": "f5d626fd-5aff-4314-9c24-52bf3b6160fc", "type": "concept", "title": "IPA"}, {"id": "fd7bd799-891b-4c0a-a04c-15988947ed93", "type": "concept", "title": "Acoustic cues"}], "description": "Students gain enough phonetic vocabulary to notice how sound is produced, heard, and socially evaluated."}, {"id": "59e3da3e-7941-4e92-9703-7c8b51a89aec", "type": "subtopic", "title": "Phonology and patterned contrast", "children": [{"id": "2c35d581-f5cc-48c6-9678-f77f62c93441", "type": "concept", "title": "Phoneme"}, {"id": "fc5fde66-ce26-4180-8cb3-dcec55db27e4", "type": "concept", "title": "Allophone"}, {"id": "7a2b5186-b826-41a9-ad5f-d30028d51262", "type": "concept", "title": "Minimal pair"}, {"id": "29e7a1b6-62cf-4f77-9df8-b979f119b469", "type": "concept", "title": "Phonotactics"}, {"id": "f68424e0-6843-4000-abe4-3aa0052b2a20", "type": "concept", "title": "Stress"}, {"id": "9fd91035-6141-44a4-bbfb-6d9c7ae99f01", "type": "concept", "title": "Tone"}], "description": "This subtopic explains how languages organize sounds into meaningful systems."}, {"id": "202cc21e-65b4-4b7e-bb63-83873e5ded70", "type": "subtopic", "title": "Accent and social perception", "children": [{"id": "37734b13-9419-4c81-b9b3-a8aa68c21a69", "type": "concept", "title": "Accent"}, {"id": "951de4fc-7d46-4a92-acfa-e7dd8222dcbb", "type": "concept", "title": "Dialect perception"}, {"id": "fc61edb9-5736-47f3-9436-4a049e8a9f1a", "type": "concept", "title": "Stigma"}, {"id": "c7fcd2cb-ed52-45d3-a0e0-be614a387aac", "type": "concept", "title": "Prestige"}, {"id": "05605f1e-7c66-4ab1-a6c0-f873bb475379", "type": "concept", "title": "Listener bias"}, {"id": "48049da4-993a-41d6-b21c-096780fd86bb", "type": "concept", "title": "Matched guise"}], "description": "Students analyze why accents become linked to race, region, class, education, ethnicity, nationality, and belonging."}]}, {"id": "85832260-16c7-4384-a0dc-e5f4070c128f", "type": "topic", "title": "Morphology, Syntax, and Discourse", "description": "Moves from word formation and sentence structure to discourse-level patterning, showing how grammar carries social consequences.", "children": [{"id": "1c4fe7b7-2da9-4be7-ab0b-b9cd8522c3f8", "type": "subtopic", "title": "Morphology and word structure", "children": [{"id": "ab88ef88-8024-41b5-b672-61a9d085ca55", "type": "concept", "title": "Morpheme"}, {"id": "2b145358-40a8-4de1-a83a-0c26832f4211", "type": "concept", "title": "Inflection"}, {"id": "48ab268b-0e73-42ef-8303-1eadfded4d89", "type": "concept", "title": "Derivation"}, {"id": "60246920-acc9-41ee-a1f3-4a0e3d3651aa", "type": "concept", "title": "Agreement"}, {"id": "34e47c16-1d6e-4f9b-876b-1b165533e28e", "type": "concept", "title": "Honorifics"}, {"id": "06a06548-12a9-4170-81b7-46b7cedeaa98", "type": "concept", "title": "Gender marking"}], "description": "Students learn how words are built and why grammatical categories can encode social meaning."}, {"id": "d86c3b64-b261-4d06-aa6a-29508ee5631c", "type": "subtopic", "title": "Syntax and social patterning", "children": [{"id": "e467861e-b4af-4d8d-af11-62ece9379a9b", "type": "concept", "title": "Phrase structure"}, {"id": "8daa251a-a91c-475d-acda-ff3abe1bfc96", "type": "concept", "title": "Word order"}, {"id": "5455e025-744c-4b17-9818-c77495dc6680", "type": "concept", "title": "Clause"}, {"id": "e1e9fdfa-dfe3-4c81-8b54-2688a2e79be3", "type": "concept", "title": "Ergativity"}, {"id": "8f157125-d250-401d-8f8d-e1ce00b9dab7", "type": "concept", "title": "Topic/comment"}, {"id": "850685bd-7304-4664-9367-bd3c24c55632", "type": "concept", "title": "Grammatical voice"}], "description": "This subtopic introduces sentence structure while connecting grammatical choices to style, genre, and authority."}, {"id": "84b8da03-c790-4a3b-91e5-b4f0e503ba11", "type": "subtopic", "title": "Discourse organization", "children": [{"id": "40023899-596c-4bad-aad4-b680083096bb", "type": "concept", "title": "Cohesion"}, {"id": "79a5cef1-8fac-4fe3-9bc1-705fabe22152", "type": "concept", "title": "Genre"}, {"id": "809af217-ae0f-49b6-aeb1-eb6a1504e2d2", "type": "concept", "title": "Narrative"}, {"id": "941132a6-f958-41ed-acf3-016b0136cec0", "type": "concept", "title": "Framing"}, {"id": "f73bd895-a104-42ca-9b4f-4d78d25638de", "type": "concept", "title": "Reported speech"}, {"id": "62a2da43-0328-4c2e-bafc-25e81e412805", "type": "concept", "title": "Intertextuality"}], "description": "Students learn how meaning unfolds across turns, stories, arguments, rituals, and institutional talk."}]}, {"id": "cdbc7a2b-36bb-4c40-8927-73ae6a1f0887", "type": "topic", "title": "Semiotics, Indexicality, and Meaning", "description": "Gives students a precise vocabulary for analyzing signs, symbols, icons, indexes, and the social life of meaning.", "children": [{"id": "8226ad3c-52da-443a-a7d0-b43eaf8efc31", "type": "subtopic", "title": "Peircean semiotics", "children": [{"id": "56755540-9e36-4cb0-b182-5582b0e74ad5", "type": "concept", "title": "Icon"}, {"id": "e61efc2a-2b08-4808-82f4-b1a8c046232b", "type": "concept", "title": "Index"}, {"id": "a17b9318-ab02-4d35-9425-baf4552c4aa7", "type": "concept", "title": "Symbol"}, {"id": "ee92d1fe-ab4a-434f-8d7c-a39a7c59cbe4", "type": "concept", "title": "Object"}, {"id": "57899449-d897-49dc-bd3c-b863160864ef", "type": "concept", "title": "Interpretant"}, {"id": "ce9df89f-5c99-4853-9bbd-6ae7fc996d09", "type": "concept", "title": "Semiotic process"}], "description": "Students learn how different kinds of signs connect form to meaning."}, {"id": "51a6b1e8-cb98-4c3d-98a3-9b61a2ec0fc7", "type": "subtopic", "title": "Indexicality and social meaning", "children": [{"id": "c8221d69-39af-429c-84f5-079692de7acf", "type": "concept", "title": "Indexical sign"}, {"id": "d569c66c-c05c-4629-bc17-fb9c745b5408", "type": "concept", "title": "Indexical order"}, {"id": "2628b47d-3124-4eac-926c-a52713c25fde", "type": "concept", "title": "Deixis"}, {"id": "bf1910b5-6d16-4c60-a155-49659ab7efeb", "type": "concept", "title": "Stance"}, {"id": "6e88d235-bac0-4259-98d6-8c1f18009193", "type": "concept", "title": "Enregisterment"}, {"id": "15ec1b5a-b4fa-409e-9075-337a7b2c3b01", "type": "concept", "title": "Social deixis"}], "description": "This subtopic shows how language points to social identities, places, stances, relationships, and contexts."}, {"id": "a51be28f-0b44-41c7-84d3-041a3269cb83", "type": "subtopic", "title": "Semiotic ideology", "children": [{"id": "f3b9ddf9-4f09-403d-b8a7-419f2b7d2818", "type": "concept", "title": "Semiotic ideology"}, {"id": "c0199677-a11d-4503-88a3-5e41f638bdfb", "type": "concept", "title": "Language ideology"}, {"id": "26eecea3-3323-4d8b-ac02-7a445da303b1", "type": "concept", "title": "Authenticity"}, {"id": "98852144-4df6-4388-8f02-d79a940f0404", "type": "concept", "title": "Voice"}, {"id": "b93724a6-667e-4df9-82f2-ecf53f7507a5", "type": "concept", "title": "Mediation"}, {"id": "af2b466f-7e7d-4f96-9083-2d333fcbe0f7", "type": "concept", "title": "Authority"}], "description": "Students examine cultural assumptions about what signs are, how they work, and what makes communication authentic or powerful."}]}, {"id": "c6ed47a2-edac-44d3-add1-be36a3330ee7", "type": "topic", "title": "Language Socialization", "description": "Studies how people learn language and culture together through participation in everyday interaction.", "children": [{"id": "43f88f53-519f-446f-96dd-b56ce6726590", "type": "subtopic", "title": "Socialization through language", "children": [{"id": "9408707e-fff0-4415-adce-7e853724b73c", "type": "concept", "title": "Caregiver speech"}, {"id": "79b6ec25-9cef-4649-a09c-e41b27295a58", "type": "concept", "title": "Scaffolding"}, {"id": "10c01d42-46b7-49ab-b0a9-cee6374b5d5d", "type": "concept", "title": "Participation"}, {"id": "7b0b58d3-bb8a-4e4f-8304-78fa2ebb44a1", "type": "concept", "title": "Routine"}, {"id": "fe82839f-3054-4f50-bf3b-9d8b23a86d6f", "type": "concept", "title": "Correction"}, {"id": "cf19ae99-cb54-4e9a-9d82-02c6c7d810d0", "type": "concept", "title": "Social norm"}], "description": "Students learn how caregivers, peers, schools, and institutions teach norms through talk."}, {"id": "8d775a33-f8d3-467d-b491-a8b55d06614e", "type": "subtopic", "title": "Socialization to use language", "children": [{"id": "e31b3767-62f6-49ac-97d0-e425182ef3ad", "type": "concept", "title": "Communicative competence"}, {"id": "1df2c8d7-64bd-4351-8b1f-a395d2e723b4", "type": "concept", "title": "Politeness"}, {"id": "4eb2452b-8f08-44c3-a153-e9d2249020ad", "type": "concept", "title": "Genre"}, {"id": "86962898-829e-421b-a73d-215641cc1448", "type": "concept", "title": "Narrative skill"}, {"id": "04dd12b9-3d5e-4b7e-a9ed-c3a300c81c2a", "type": "concept", "title": "Emotion talk"}, {"id": "c5d6da4b-564f-4ea8-85ed-6f06af238f2d", "type": "concept", "title": "Authority"}], "description": "This subtopic examines how learners acquire culturally specific genres, politeness, stance, emotion, and authority."}, {"id": "2f0868c1-3ed3-447e-9ba1-fab324d86198", "type": "subtopic", "title": "Life-course language learning", "children": [{"id": "c7139610-dbb6-48b9-873f-5e19ab887aa7", "type": "concept", "title": "Peer socialization"}, {"id": "861e93d4-854d-472e-ab9a-fb95a32b5a8b", "type": "concept", "title": "Workplace language"}, {"id": "dd53aceb-2ab8-4fcc-830a-bd73689aef72", "type": "concept", "title": "Second-language learning"}, {"id": "b7cdee17-7ff2-4076-bd9f-e9f57b34be2e", "type": "concept", "title": "Religious language"}, {"id": "87a6c789-0eb0-4e24-a084-6b34fe1526d4", "type": "concept", "title": "Digital socialization"}, {"id": "1e74e4ca-e497-46e7-9c14-d7ac02a20204", "type": "concept", "title": "Aging"}], "description": "Students broaden language socialization beyond childhood to migration, work, religion, schooling, online life, and aging."}]}, {"id": "3467f173-957e-48f2-b20d-9023434a5869", "type": "topic", "title": "Speech Communities, Registers, and Style", "description": "Explores how people recognize ways of speaking as belonging to groups, settings, identities, and activities.", "children": [{"id": "e23e19eb-8f2a-4e82-b957-f28e035b77d4", "type": "subtopic", "title": "Speech community and community of practice", "children": [{"id": "d7e819da-d814-4f40-9c86-61cc7af3c436", "type": "concept", "title": "Speech community"}, {"id": "95e99a0f-bc64-4fb8-a7fb-35383911cd7e", "type": "concept", "title": "Community of practice"}, {"id": "deb91142-f74c-4934-b3bf-3a1e20a23cea", "type": "concept", "title": "Network"}, {"id": "f67be4d7-9c9f-4515-ba2e-ea0a8f613d86", "type": "concept", "title": "Norm"}, {"id": "d58bda54-0f94-45f8-a21b-ed68a556c68e", "type": "concept", "title": "Membership"}, {"id": "e0663641-3dfe-42a8-8e87-dabe6732edc5", "type": "concept", "title": "Practice"}], "description": "Students compare ways of defining language communities through shared norms, participation, and interaction."}, {"id": "11cff1ea-6d23-42f7-9b2a-db5ceb25b02f", "type": "subtopic", "title": "Register and enregisterment", "children": [{"id": "27d5f265-d1c6-47f2-a7de-57c4af6a9370", "type": "concept", "title": "Register"}, {"id": "2f833d34-4fe6-4b78-8c0f-8fc33391ac43", "type": "concept", "title": "Enregisterment"}, {"id": "1ad53943-4cda-45dc-903c-c9c139f43f72", "type": "concept", "title": "Style"}, {"id": "e3c697c6-373d-4b4a-861a-ecf70fb334a5", "type": "concept", "title": "Genre"}, {"id": "fabd0ddf-a08d-4641-849d-cdf4a06a935d", "type": "concept", "title": "Persona"}, {"id": "90ebe2b5-ac90-49bf-b5be-6a6ffddc7735", "type": "concept", "title": "Metapragmatic label"}], "description": "This subtopic shows how styles become socially recognizable as professional, religious, youthful, elite, rural, formal, or authentic."}, {"id": "83e474c2-8e72-404d-988c-8d51ca3cfd50", "type": "subtopic", "title": "Style-shifting and audience design", "children": [{"id": "6ccf7660-00c9-49d7-bf45-249ef19fa488", "type": "concept", "title": "Style-shifting"}, {"id": "04be6efa-1330-469a-8d8c-291b44b05e23", "type": "concept", "title": "Audience design"}, {"id": "0499f187-438f-4098-b473-70529edd06f4", "type": "concept", "title": "Accommodation"}, {"id": "143f47fd-fa77-4d20-901a-4851cf4d12b5", "type": "concept", "title": "Footing"}, {"id": "4c8d8b57-3c08-44bf-bd46-4db54fbe28bd", "type": "concept", "title": "Stance-taking"}, {"id": "bf3097d8-297a-42c7-a95a-4406f6bf9153", "type": "concept", "title": "Persona management"}], "description": "Students analyze how speakers adapt language to audiences, situations, identities, and goals."}]}, {"id": "ad167418-d72f-4f6f-9c64-3366535670ce", "type": "topic", "title": "Language Ideology and Power", "description": "Places belief about language at the center of inequality, authority, education, race, nation, class, and legitimacy.", "children": [{"id": "719bc841-6d3e-4381-aa4d-3e45d1fa401f", "type": "subtopic", "title": "Language ideology", "children": [{"id": "ddce0b3f-3cdd-45a1-8dd8-b8e6d5f603af", "type": "concept", "title": "Standard language ideology"}, {"id": "a43e64f9-605b-4d2a-b3c8-183b10a8d267", "type": "concept", "title": "Purism"}, {"id": "386023d7-d56a-47a0-a846-b738020a6d3e", "type": "concept", "title": "Correctness"}, {"id": "de4f0dcd-18fa-4fc4-abce-65581138d71f", "type": "concept", "title": "Authenticity"}, {"id": "f2b29803-ecba-4341-9a00-4