, "title": "Queer linguistics"}, {"id": "4843e143-bc82-43b1-b8ab-6f5f1f273f97", "type": "concept", "title": "Indexicality"}, {"id": "07df40c4-e0af-4a1a-8885-18d36c25eb1d", "type": "concept", "title": "Style"}, {"id": "c527ff2c-a584-46fe-bc91-818c40b6e9ba", "type": "concept", "title": "Stance"}, {"id": "724aa73e-1098-4ddd-a7b0-567687379f22", "type": "concept", "title": "Interactional identity"}], "description": "This subtopic explores how people produce, contest, and stylize gender and sexuality through interaction."}, {"id": "2fd760fa-583f-4897-8ddc-e5e0938d2acb", "type": "subtopic", "title": "Class, mobility, and respectability", "children": [{"id": "fe560584-b6f1-4f50-a761-3dd98f7b45c0", "type": "concept", "title": "Respectability"}, {"id": "e70a3279-43fe-458a-8221-9b82a7133963", "type": "concept", "title": "Prestige dialect"}, {"id": "2e9e6149-07fa-42d8-9539-fe5706f86aa1", "type": "concept", "title": "Class accent"}, {"id": "885b35b2-9df5-4c85-a9c2-8fdff4cb8054", "type": "concept", "title": "Professional speech"}, {"id": "f8cf5eb3-5bcb-4353-84cf-ddd4635d2380", "type": "concept", "title": "Linguistic insecurity"}, {"id": "b36b63fb-0123-4f77-99e6-a831066103ed", "type": "concept", "title": "Upward mobility"}], "description": "Students examine language as a resource and burden in education, work, migration, and social mobility."}]}, {"id": "5494592d-b00b-4620-a1eb-f6a9c9f29a88", "type": "topic", "title": "Language Change, Contact, and Endangerment", "description": "Frames language change as socially embedded and connects language contact to migration, colonialism, education, media, and policy.", "children": [{"id": "f093a178-ce9c-4cce-bfc8-6c0c6d44f551", "type": "subtopic", "title": "Language contact", "children": [{"id": "b3e65221-9ea6-4756-8b1b-567406297990", "type": "concept", "title": "Borrowing"}, {"id": "66bd278e-d9f9-41a8-9e7d-d2e0e970d6f2", "type": "concept", "title": "Calque"}, {"id": "8a20b28d-d671-4c77-ba7f-34da6b2d3653", "type": "concept", "title": "Pidgin"}, {"id": "28958b56-65f6-4d02-a0f9-c727d90ac37d", "type": "concept", "title": "Creole"}, {"id": "e559f3ba-43dd-49e6-ba6a-fdaa5b8c4341", "type": "concept", "title": "Convergence"}, {"id": "dbdb9efa-c3ec-4760-b5a9-59bb4d06e992", "type": "concept", "title": "Contact zone"}], "description": "Students learn how languages influence each other through borrowing, convergence, pidgins, creoles, and mixed codes."}, {"id": "dd002550-abee-420a-a74a-046057df2b14", "type": "subtopic", "title": "Language shift and endangerment", "children": [{"id": "69b4823c-f90a-4ed6-9340-cb33137852a7", "type": "concept", "title": "Language shift"}, {"id": "d062af77-0e6d-41f2-88ac-1f8eeb9c5151", "type": "concept", "title": "Endangerment"}, {"id": "c904cee0-d464-4514-8932-acf58772c468", "type": "concept", "title": "Vitality"}, {"id": "0e7fd6bc-b008-43ed-bbf1-07c7926ccb8e", "type": "concept", "title": "Domain loss"}, {"id": "a84fc969-ec83-480e-9a9a-7c3f5906ae90", "type": "concept", "title": "Intergenerational transmission"}, {"id": "1ba8babc-7b60-4888-ac19-0e0bb6d020fa", "type": "concept", "title": "Dormant language"}], "description": "This subtopic examines why communities shift languages and what is lost, transformed, or reclaimed."}, {"id": "3ad44303-801e-4d0d-a837-a08294df69e9", "type": "subtopic", "title": "Revitalization and reclamation", "children": [{"id": "3cb65065-9030-495d-90ae-c653e9ca02df", "type": "concept", "title": "Revitalization"}, {"id": "ae8d0872-ae10-4ae4-b4eb-732453b67850", "type": "concept", "title": "Reclamation"}, {"id": "e53e1695-4a0d-4b0b-a39b-8b0d6df5d904", "type": "concept", "title": "Immersion"}, {"id": "0ae82978-14d1-4296-bf52-9fec4a1fbadf", "type": "concept", "title": "Master-apprentice model"}, {"id": "960167f2-0356-4d53-9d86-55c4b07986da", "type": "concept", "title": "Orthography"}, {"id": "77c97c99-5202-44ab-add4-911d12e73664", "type": "concept", "title": "Community control"}], "description": "Students study community-led work to teach, document, normalize, and reclaim threatened languages."}]}, {"id": "628a1f53-33a8-4252-a8d5-94231a4da60d", "type": "topic", "title": "Narrative, Performance, and Ritual Speech", "description": "Studies storytelling, performance, ritual, poetics, and verbal art as key sites of cultural meaning and social authority.", "children": [{"id": "d7625798-c4b4-4a57-abb6-668c0ac5c550", "type": "subtopic", "title": "Narrative structure and identity", "children": [{"id": "aa8b26c1-07de-4d53-ab7f-be447511d087", "type": "concept", "title": "Labov"}, {"id": "bc6b6350-35f3-4260-a786-f26e87ffc603", "type": "concept", "title": "Orientation"}, {"id": "49d502b3-6a9b-43ef-bb21-3499ed2e2382", "type": "concept", "title": "Evaluation"}, {"id": "bc2ad5c2-9910-400a-99c5-0bfb024ffb3d", "type": "concept", "title": "Coda"}, {"id": "e39ab0a2-409d-47dd-b868-e817f527cc2a", "type": "concept", "title": "Narrative identity"}, {"id": "0be4c54f-dbef-40c6-8bc7-a01466749cb6", "type": "concept", "title": "Life history"}], "description": "Students learn how stories organize memory, selfhood, morality, blame, and belonging."}, {"id": "b02a78f7-4b44-4d0c-acc6-7e2bf1f384f9", "type": "subtopic", "title": "Performance and verbal art", "children": [{"id": "3fa5a5e5-35c0-453a-a925-f275a92c7e11", "type": "concept", "title": "Performance"}, {"id": "817de5ec-79a6-4fa9-bda6-21f62bf5f274", "type": "concept", "title": "Poetics"}, {"id": "c501603a-06e8-42f4-9250-7407df61f4bb", "type": "concept", "title": "Parallelism"}, {"id": "b1e20ca5-c008-4b4b-ad64-38edc64b432a", "type": "concept", "title": "Repetition"}, {"id": "51b27b2f-d739-40f6-9fa0-bb442f60b515", "type": "concept", "title": "Audience"}, {"id": "06024541-3e19-4db6-aee9-bbc187057128", "type": "concept", "title": "Verbal art"}], "description": "This subtopic examines how artistry, audience, timing, voice, and repetition make speech socially powerful."}, {"id": "9bef45ec-4b17-4340-a2bb-ebf623a66f53", "type": "subtopic", "title": "Ritual and authoritative speech", "children": [{"id": "f8517ac